"""Write docs/cost-estimate.md from the cost model."""
from cost_model import summarize, TIERS, FX, EVAL_Q

S = summarize()
c = lambda x, d=0: f"${x:,.{d}f}"
o = ["# Cost estimate", "",
     f"Monthly cost in CAD for production plus dev and test, Canadian regions, list prices converted at USD 1 = CAD {FX:.2f} "
     "(Bank of Canada, November 2026). Generated by `cost-model/gen_cost_md.py`; edit assumptions in `cost_model.py`.", "",
     "## Summary", "",
     "| Tier | Questions/mo | Users | AWS | Google Cloud | AWS per question | GCP per question |",
     "| --- | --: | --: | --: | --: | --: | --: |"]
for t in TIERS:
    o.append(f"| {t} | {TIERS[t]['q']:,} | {TIERS[t]['users']:,} | {c(S[t]['AWS']['cad'])} | {c(S[t]['GCP']['cad'])} "
             f"| {c(S[t]['AWS']['per_q_cad'], 3)} | {c(S[t]['GCP']['per_q_cad'], 3)} |")
o += ["", f"Per-question figures divide by user questions only; {EVAL_Q:,} evaluation-set runs a month are included in every tier.", "",
      "Model price explains the gap: keeping inference in Canada limits each cloud to one model family today "
      "(Claude Haiku 5.5 via Bedrock Canada inference; Gemini 3.5 Flash on Vertex AI Montréal). At pilot volume fixed "
      "infrastructure dominates and Google Cloud is cheaper; from production volume, tokens dominate and AWS is cheaper.", "",
      "**Basis:** S = unit price confirmed from a November 2026 source; L = published US list price scaled by a regional "
      "factor (1.10, or 1.40 for Cloud Run Tier 2); A = planning allowance. Validate L lines in the AWS and Google Cloud "
      "pricing calculators before budgeting.", ""]
for cloud, name in (("AWS", "AWS"), ("GCP", "Google Cloud")):
    o += [f"## {name}", "", "| Layer | Service | Basis | Pilot | Production | Scale |", "| --- | --- | :-: | --: | --: | --: |"]
    for i, l in enumerate(S["Pilot"][cloud]["lines"]):
        vals = " | ".join(c(S[t][cloud]["lines"][i]["cad"]) for t in TIERS)
        o.append(f"| {l['layer']} | {l['service']} | {l['basis']} | {vals} |")
    o.append("| **Total** | | | " + " | ".join(f"**{c(S[t][cloud]['cad'])}**" for t in TIERS) + " |")
    o.append("")
o += ["## LLM cost by model option (CAD/month)", "",
      "| Option | Residency | Pilot | Production | Scale |", "| --- | --- | --: | --: | --: |"]
for label, res, k in [("Claude Haiku 5.5, all four calls (costed)", "Canada", "aws_haiku_canada"),
                      ("Haiku 5.5 + Claude Sonnet 5.5 for planner and narrator", "Leaves Canada", "aws_sonnet_global_for_planner_narrator"),
                      ("Gemini 3.5 Flash, Montréal (costed)", "Canada", "gcp_gemini35_montreal"),
                      ("Gemini 3.8 Flash, global, 2027 standard rate", "Leaves Canada", "gcp_gemini38_global_2027")]:
    o.append(f"| {label} | {res} | " + " | ".join(c(S[t]["sensitivity"][k]) for t in TIERS) + " |")
o += ["", "## Not included", "",
      "Staff time, support plans, egress beyond free tiers, taxes, prompt caching savings, commitment discounts, "
      "and statistical matching work for a fused CIUS–Census file.", "",
      "## Pricing sources", "",
      "- [Bedrock Canada cross-Region inference for Claude Haiku 5.5](https://aws-news.com/article/2026-10-30-amazon-bedrock-now-offers-canada-cross-region-inference-for-claude-haiku-55)",
      "- [AWS Bedrock pricing, CloudForecast](https://www.cloudforecast.io/blog/aws-bedrock-pricing/)",
      "- [AWS Bedrock pricing, Economize (regional +10%)](https://www.economize.cloud/blog/aws-bedrock-pricing/)",
      "- [Aurora Serverless v2 pricing, usage.ai](https://www.usage.ai/blogs/aws/rds/aurora-serverless-v2/)",
      "- [Gemini API pricing, metacto](https://www.metacto.com/blogs/the-true-cost-of-google-gemini-a-guide-to-api-pricing-and-integration)",
      "- [Gemini API pricing, AI Business Weekly](https://aibusinessweekly.net/p/gemini-api-pricing)",
      "- [Cloud Run locations and pricing tiers](https://docs.cloud.google.com/run/docs/locations)",
      "- [Cloud SQL pricing](https://cloud.google.com/sql/pricing)",
      "- [Cloud SQL C4A regional prices, Spare Cores](https://sparecores.com/database/gcp/db-c4a-highmem-2)",
      "- [Bank of Canada daily exchange rates](https://www.bankofcanada.ca/rates/exchange/daily-exchange-rates/)", ""]
open("../docs/cost-estimate.md", "w").write("\n".join(o))
print("wrote docs/cost-estimate.md")
